def rewrite(p,new,tracked):
 global rev
 old=txt(p)
 if old==new:return
 assert not p.findall('.//w:drawing',NS)
 chars=[]
 for run in p.findall('.//w:r',NS):
  prop=run.find('w:rPr',NS)
  t=''.join(run.xpath('./w:t/text()',namespaces=NS))
  chars += [prop]*len(t)
 # Edited paragraphs contain plain runs only, apart from harmless bookmarks/proofing tags.
 assert len(chars)==len(old),(old[:70],len(chars),len(old))
 base=next((x for x in chars if x is not None),None)
 for c in list(p):
  if c.tag!=q('pPr'):p.remove(c)
 def add(s,start,deleted=False,inserted=False):
  nonlocal p
  global rev
  if not s:return
  parent=p
  if tracked and (deleted or inserted):
   rev+=1;parent=E.SubElement(p,q('del' if deleted else 'ins'),{q('id'):str(rev),q('author'):'Editorial review',q('date'):'2026-10-19T18:00:00Z'})
  props=chars[start:start+len(s)] if not inserted else [chars[min(start,len(chars)-1)] if chars else base]*len(s)
  if len(props)!=len(s):props=[base]*len(s)
  j=0
  while j<len(s):
   k=j+1
   while k<len(s) and props[k] is props[j]:k+=1
   r=E.SubElement(parent,q('r'))
   if props[j] is not None:r.append(deepcopy(props[j]))
   t=E.SubElement(r,q('delText' if tracked and deleted else 't'));t.set('{http://www.w3.org/XML/1998/namespace}space','preserve');t.text=s[j:k];j=k
 ot=re.findall(r'\S+\s*|\s+',old); nt=re.findall(r'\S+\s*|\s+',new);offs=[0]
 for t in ot:offs.append(offs[-1]+len(t))
 for op,a,b,c,d in difflib.SequenceMatcher(None,ot,nt,autojunk=False).get_opcodes():
  if op=='equal':add(''.join(ot[a:b]),offs[a])
  else:
   if tracked and op in ('delete','replace'):add(''.join(ot[a:b]),offs[a],deleted=True)
   if op in ('insert','replace'):add(''.join(nt[c:d]),offs[a],inserted=True)
